fn solve(m: i8, d: i8) -> i8 {
    // Number of days in each month for a non-leap year
    let days_in_month = match m {
        1  => 31,
        2  => 28,
        3  => 31,
        4  => 30,
        5  => 31,
        6  => 30,
        7  => 31,
        8  => 31,
        9  => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _  => unreachable!(), // m is guaranteed to be in 1..=12
    };

    // Total slots = leading empty days (d-1) + days in the month
    let total_slots = (d - 1) + days_in_month;

    // Number of weeks = ceil(total_slots / 7)
    // We can compute ceil(x/7) as (x + 6) / 7 using integer division
    (total_slots + 6) / 7
}